mapper.select:
SELECT *
FROM business_operation_log

    user_id = #{userId}
    AND trigger_type = 'USER_ACTION'
    AND user_visible = 1
    AND occurred_at >= #{since}
    AND success = #{success}
    AND module = #{module}
    AND function_name = #{functionName}

ORDER BY occurred_at DESC, id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM business_operation_log

    user_id = #{userId}
    AND trigger_type = 'USER_ACTION'
    AND user_visible = 1
    AND occurred_at >= #{since}
    AND success = #{success}
    AND module = #{module}
    AND function_name = #{functionName}
